<?php
require_once __DIR__.'/../auth_check.php'; AccessManager::requirePageAccess('factures_vente.php');
require_once __DIR__.'/../model/Database.php'; require_once __DIR__.'/../model/FactureVente.php';
$invoice=(new FactureVente(Database::getConnection()))->getById((int)($_GET['id']??0));
if(!$invoice){http_response_code(404);exit('Facture introuvable.');}
$items=json_decode((string)($invoice['items_json']??'[]'),true)?:[];
$ht=0.0;$tax=0.0;foreach($items as $item){$line=(float)($item['quantity']??1)*(float)($item['amount']??0);$ht+=$line;$tax+=$line*(float)($item['tax_rate']??0);}
$discount=(float)($invoice['discount']??0);$total=max(0,$ht+(empty($invoice['tax_not_invoiced'])?$tax:0)-$discount);
function fv_h($v){return htmlspecialchars((string)$v,ENT_QUOTES,'UTF-8');}
require_once __DIR__.'/../model/CompanyBranding.php';
$invoiceBrand=CompanyBranding::get();
$invoicePalette=CompanyBranding::palette();
$invoicePrimary=$invoicePalette['primary'];
$invoiceOnPrimary=CompanyBranding::contrastColor($invoicePrimary);
?><!doctype html><html lang="fr"><head><meta charset="utf-8"><title><?=fv_h($invoice['reference_interne']??'Facture')?></title><meta name="viewport" content="width=device-width"><style>body{margin:0;background:#eef2f7;color:#172348;font:14px Arial,sans-serif}.sheet{width:min(210mm,calc(100% - 32px));min-height:297mm;margin:24px auto;background:#fff;box-shadow:0 18px 55px #17234822}.head{padding:30px 38px;background:<?=fv_h($invoicePrimary)?>;color:<?=fv_h($invoiceOnPrimary)?>;border-bottom:4px solid <?=fv_h($invoicePalette['accent'])?>}.brand{font-size:28px;font-weight:900}.meta,.totals{display:grid;grid-template-columns:1fr 1fr;gap:24px;padding:28px 38px}.box{border:1px solid #dce4ef;border-radius:12px;padding:16px}table{width:calc(100% - 76px);margin:0 38px;border-collapse:collapse}th,td{padding:12px;border-bottom:1px solid #e5eaf1;text-align:left}th{background:#f5f7fb;font-size:11px;text-transform:uppercase}.right{text-align:right}.total{font-size:22px;font-weight:900;color:#274b91}.actions{position:sticky;top:0;padding:12px;text-align:center;background:#172348}.actions a,.actions button{display:inline-block;margin:0 5px;border:0;border-radius:8px;padding:10px 16px;background:<?=fv_h($invoicePrimary)?>;color:<?=fv_h($invoiceOnPrimary)?>;border:1px solid <?=fv_h($invoicePalette['accent'])?>;font-weight:800;text-decoration:none}@media print{body{background:#fff}.actions{display:none}.sheet{width:100%;margin:0;box-shadow:none}}</style></head><body><div class="actions"><button onclick="print()">Imprimer / PDF</button><?php if(!empty($invoice['facture_file_path'])):?><a target="_blank" href="../<?=fv_h($invoice['facture_file_path'])?>">Voir le fichier transmis</a><?php endif;?></div><article class="sheet"><header class="head"><div class="brand"><?php if(!empty($invoiceBrand['logo_path'])):?><img src="../branding_asset.php?type=logo" alt="Logo" style="max-width:150px;max-height:65px;background:#fff;padding:6px;border-radius:5px"><?php endif;?> <?=fv_h($invoiceBrand['company_name'])?></div><h1>FACTURE DE VENTE</h1><div><?=fv_h($invoice['reference_interne']??'')?></div></header><section class="meta"><div class="box"><strong>Client</strong><h2><?=fv_h($invoice['client_company_name']??'')?></h2><div><?=fv_h($invoice['client_phone']??'')?> · <?=fv_h($invoice['client_email']??'')?></div></div><div class="box"><strong>Date de facturation</strong><h2><?=!empty($invoice['invoice_date'])?date('d/m/Y',strtotime($invoice['invoice_date'])):'—'?></h2><div><?=($invoice['paiement_statut']??'emise')==='payee'?'Payée / encaissée':'Émise / à percevoir'?></div></div></section><table><thead><tr><th>Désignation</th><th>Qté</th><th class="right">Prix unitaire</th><th class="right">Total HT</th></tr></thead><tbody><?php foreach($items as $item):$line=(float)($item['quantity']??1)*(float)($item['amount']??0);?><tr><td><?=fv_h($item['description']??'')?></td><td><?=fv_h($item['quantity']??1)?></td><td class="right"><?=number_format((float)($item['amount']??0),0,',',' ')?></td><td class="right"><?=number_format($line,0,',',' ')?></td></tr><?php endforeach;?></tbody></table><section class="totals"><div class="box"><?php if(!empty($invoice['tax_not_invoiced'])):?><strong>TVA non facturée</strong><p>La TVA est présentée à titre informatif et n’est pas ajoutée au montant exigible.</p><?php else:?><strong>TVA facturée</strong><?php endif;?></div><div class="box right"><div>Total HT : <?=number_format($ht,0,',',' ')?> FCFA</div><div>TVA : <?=number_format($tax,0,',',' ')?> FCFA</div><?php if($discount>0):?><div>Remise commerciale : − <?=number_format($discount,0,',',' ')?> FCFA</div><?php endif;?><p class="total">Net à payer : <?=number_format($total,0,',',' ')?> FCFA</p></div></section><footer style="margin:20px 38px;padding:15px 0;border-top:2px solid <?=fv_h($invoicePalette['accent'])?>;font-size:11px"><?=fv_h(implode(' · ',array_filter([$invoiceBrand['legal_name'],$invoiceBrand['address'],$invoiceBrand['phone'],$invoiceBrand['email'],$invoiceBrand['rccm'],$invoiceBrand['tax_number']])))?></footer></article></body></html>
